WITH cleaned AS (SELECT *, CASE WHEN amount >= 4300 THEN 'High' WHEN amount >= 1900 THEN 'Medium' ELSE 'Low' END amount_band, IF(is_flagged, 'Yes', 'No') is_flagged_label, COALESCE(merchant, 'DIRECT') merchant_clean FROM transactions WHERE merchant IS NOT NULL AND merchant IS DISTINCT FROM 'Starbucks'), prev_events AS (SELECT *, LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) AS prev_txn_time FROM cleaned), flagged AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM prev_events), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT DATE_TRUNC('MONTH', txn_time) AS activity_month, DATE_TRUNC('WEEK', prev_txn_time) AS week_start, ROUND(AVG(is_new_burst), 2) AS avg_is_new_burst, ROUND(AVG(island_id), 2) AS avg_island_id, SIZE(COLLECT_SET(txn_type)) AS num_txn_types FROM sessionized GROUP BY CUBE (DATE_TRUNC('MONTH', txn_time), DATE_TRUNC('WEEK', prev_txn_time));
